using SchoolEnrollmentAPI.Models; using SchoolEnrollmentAPI.Repositories;
namespace SchoolEnrollmentAPI.Services { public class AlunoService { private readonly AlunoRepository _repo = new AlunoRepository(); public PagedResult<Aluno> Listar(string nome, int pagina, int tamanho) { return _repo.Listar(nome, pagina, tamanho); } public Aluno Obter(int id) { return _repo.Obter(id); } public Aluno Criar(AlunoRequest request) { var aluno = Converter(request); aluno.Id = _repo.Criar(aluno); return aluno; } public bool Atualizar(int id, AlunoRequest request) { return _repo.Atualizar(id, Converter(request)); } public bool Excluir(int id) { return _repo.Desativar(id); } private static Aluno Converter(AlunoRequest r) { return new Aluno { Nome = r.Nome.Trim(), Email = r.Email.Trim(), DataNascimento = r.DataNascimento.Value, Ativo = true }; } } }
